#!/usr/bin/env python3
"""Real ecommerce MVC journey against an ephemeral localhost enterprise demo only.

Uses genuine Identity, tenant selection, rendered forms, CSRF, server pricing, stock/GL
and relational verification. Does not test visual browser rendering, production SQL
Server or real tax/payment providers. No external URL, secrets or customer DB accepted.
"""
from decimal import Decimal
from enterprise_http_fixture import Fixture, Forms

with Fixture('ecommerce') as f:
    customer=f.login(1); staff=f.login(1,reviewer=True); outsider=f.login(2)
    company=f.scalar("SELECT Id FROM Companies WHERE Slug='demo-farm-1'")
    product,stock=f.query('SELECT Id,StockItemId FROM EcommerceProducts WHERE CompanyId=?',(company,))[0]
    def state(order):return f.query('SELECT Status,PaymentStatus,NetAmount,TaxAmount,GrossAmount FROM EcommerceOrders WHERE Id=?',(order,))[0]
    def stock_state():return tuple(Decimal(str(x)) for x in f.query('SELECT QuantityOnHand,ReservedQuantity FROM StockItems WHERE Id=?',(stock,))[0])
    initial=stock_state(); initial_orders=f.scalar('SELECT COUNT(*) FROM EcommerceOrders')
    f.page(customer,'/Ecommerce'); f.page(staff,'/Ecommerce/manage'); f.page(customer,'/Ecommerce/orders'); f.page(staff,'/Ecommerce/staff/orders')
    f.check('Anonymous storefront requires sign-in',f.anonymous.request('/Ecommerce').status==302)
    no_match=f.page(customer,'/Ecommerce?search=NO-SUCH-FICTIONAL-PRODUCT&category=DEMO%20feed&page=999')
    f.check('Catalog search/category filter and excessive page clamp work','No published products match' in no_match.text)
    def edit_product_form():
        forms=Forms(f.page(staff,'/Ecommerce/manage').text).forms
        return next(x for x in forms if x['action']=='/Ecommerce/product' and x['fields'].get('id')==str(product))
    edit=edit_product_form()
    response=staff.submit(edit,{'description':'','category':'','published':'false'})
    f.check('Catalog edit accepts optional blank fields and unpublishes the product',response.status==302 and f.scalar('SELECT Published FROM EcommerceProducts WHERE Id=?',(product,))==0)
    f.check('Unpublished catalog product is hidden from customer','/Ecommerce/cart/line' not in f.page(customer,'/Ecommerce').text)
    stale=staff.submit(edit,{'published':'true'})
    f.check('Stale catalog revision cannot republish after another update',stale.status==302 and f.scalar('SELECT Published FROM EcommerceProducts WHERE Id=?',(product,))==0)
    response=staff.submit(edit_product_form(),{'description':'Fictional HTTP product','category':'DEMO feed','published':'true'})
    f.check('Fresh catalog form republishes using approved policy',response.status==302 and f.scalar('SELECT Published FROM EcommerceProducts WHERE Id=?',(product,))==1)
    manage_page=f.page(staff,'/Ecommerce/manage')
    f.check('Ecommerce product price form uses locked two-decimal currency step','name="netUnitPrice" type="number" min="0.01" step="0.01"' in manage_page.text)
    catalog_form=f.form(customer,'/Ecommerce','/Ecommerce/cart/line')
    response=customer.submit(catalog_form,{'productId':product,'quantity':'2','netUnitPrice':'0.001','grossAmount':'0.001','paymentStatus':'Paid'})
    f.check('Rendered catalog form updates customer cart',response.status==302 and response.location=='/Ecommerce/cart')
    cart_page=f.page(customer,'/Ecommerce/cart'); checkout=Forms(cart_page.text).get('/Ecommerce/checkout')
    f.check('Cart shows explicit tax, total, payment and collection confirmation','Order total' in cart_page.text and 'configured tax' in cart_page.text and 'branch collection terms' in cart_page.text)
    blocked=customer.request('/Ecommerce/checkout',fields={'checkoutToken':checkout['fields']['checkoutToken'],'confirmOrder':'true'})
    f.check('Checkout without CSRF is rejected',blocked.status==400 and f.scalar('SELECT COUNT(*) FROM EcommerceOrders')==initial_orders)
    missing=customer.submit(checkout,{'confirmOrder':'false'})
    f.check('Checkout requires explicit confirmation',missing.status==302 and f.scalar('SELECT COUNT(*) FROM EcommerceOrders')==initial_orders)
    response=customer.submit(checkout,{'confirmOrder':'true','price':'0.001','customerId':'999999','paymentStatus':'Paid'})
    f.check('Confirmed checkout returns own created order',response.status==302 and response.location.startswith('/Ecommerce/orders/'))
    order=int(response.location.rsplit('/',1)[1]); own=f'/Ecommerce/orders/{order}'; staff_route=f'/Ecommerce/staff/orders/{order}'
    snap=state(order); line=f.query('SELECT Id,NetUnitPrice,Quantity FROM EcommerceOrderLines WHERE EcommerceOrderId=?',(order,))[0]
    server_price=Decimal(str(f.scalar('SELECT NetUnitPrice FROM EcommerceProducts WHERE Id=?',(product,))))
    f.check('Server prices and configured tax defeat forged totals/payment/customer fields',Decimal(str(line[1]))==server_price and Decimal(str(snap[2]))==2*server_price and Decimal(str(snap[3]))>0 and snap[1]=='PendingUnverified')
    f.check('Checkout reserves without deducting physical stock',stock_state()==(initial[0],initial[1]+2))
    repeated=customer.submit(checkout,{'confirmOrder':'true'})
    f.check('Duplicate checkout returns same order and never double reserves',repeated.location==own and f.scalar('SELECT COUNT(*) FROM EcommerceOrders')==initial_orders+1 and stock_state()==(initial[0],initial[1]+2))
    f.page(customer,own)
    f.check('Another tenant cannot open the customer order',outsider.request(own).status==404)
    foreign_order=f.scalar('SELECT Id FROM EcommerceOrders WHERE CompanyId<>? ORDER BY Id LIMIT 1',(company,))
    f.check('Own endpoint cannot open a foreign order despite administrator account',customer.request(f'/Ecommerce/orders/{foreign_order}').status==404)
    # Create a second profile through actual staff forms to verify same-tenant owner isolation.
    party_form=f.form(staff,'/Parties','/Parties/create')
    response=staff.submit(party_form,{'kind':'Customer','code':'HTTP-WEB-SECOND','name':'Fictional second web customer','email':'','phone':'','address':''})
    f.check('Existing party UI creates the separate fictional customer',response.status==302)
    party=f.scalar("SELECT Id FROM TradingParties WHERE CompanyId=? AND Code='HTTP-WEB-SECOND'",(company,))
    identity=f.scalar("SELECT Id FROM AspNetUsers WHERE Email='farmreviewer1@example.invalid'")
    link=f.form(staff,'/Ecommerce/manage','/Ecommerce/customer-link')
    response=staff.submit(link,{'existingUserId':identity,'partyId':party,'confirmIdentityVerified':'true'})
    f.check('Customer linking uses verified scoped existing identity',response.status==302 and f.scalar('SELECT COUNT(*) FROM EcommerceCustomers WHERE UserId=?',(identity,))==1)
    f.check('Another customer in the same tenant cannot read own-order endpoint',staff.request(own).status==404)
    approve=f.form(staff,staff_route,staff_route+'/approve')
    response=staff.submit(approve,{'reviewNote':'PRIVATE INTERNAL HTTP REVIEW NOTE','confirmReview':'true'})
    f.check('Staff reviews actual order form',response.status==302 and state(order)[0]=='Approved')
    repeated=staff.submit(approve,{'reviewNote':'STALE REVIEW','confirmReview':'true'})
    f.check('Stale approval cannot append another review',repeated.status==302 and f.scalar("SELECT COUNT(*) FROM EcommerceOrderEvents WHERE EcommerceOrderId=? AND Action='Approved'",(order,))==1)
    f.check('Customer history redacts internal review notes','PRIVATE INTERNAL HTTP REVIEW NOTE' not in f.page(customer,own).text)
    fulfill=f.form(staff,staff_route,staff_route+'/fulfill')
    response=staff.submit(fulfill,{'confirmFulfillment':'true','paymentStatus':'Paid'})
    f.check('Reviewed fulfillment posts and remains payment-unverified',response.status==302 and state(order)[:2]==('Fulfilled','PendingUnverified'))
    staff.submit(fulfill,{'confirmFulfillment':'true'})
    f.check('Repeated fulfillment consumes reservation and creates one finance link',stock_state()==(initial[0]-2,initial[1]) and f.scalar('SELECT COUNT(*) FROM EcommerceFulfillments WHERE EcommerceOrderLineId=?',(line[0],))==1)
    finance=f.scalar('SELECT FinanceDocumentId FROM EcommerceFulfillments WHERE EcommerceOrderLineId=?',(line[0],))
    voucher=f.scalar('SELECT VoucherId FROM FinanceDocuments WHERE Id=?',(finance,))
    ledger=f.query('SELECT AccountCode,Debit,Credit FROM VoucherLines WHERE VoucherId=?',(voucher,))
    f.check('Fulfillment voucher balances gross receivable net sale and tax',sum(Decimal(str(x[1])) for x in ledger)==sum(Decimal(str(x[2])) for x in ledger) and any(x[0]=='2200' and Decimal(str(x[2]))==Decimal(str(snap[3])) for x in ledger))
    sales=f.form(staff,'/Sales','/Sales/return'); old_returns=f.scalar('SELECT COUNT(*) FROM StockDocumentReturns WHERE FinanceDocumentId=?',(finance,))
    response=staff.submit(sales,{'documentId':finance,'quantity':'1','reference':'HTTP-GENERIC-BYPASS'})
    f.check('Generic sales-return form cannot bypass original ecommerce tax allocation',response.status==302 and f.scalar('SELECT COUNT(*) FROM StockDocumentReturns WHERE FinanceDocumentId=?',(finance,))==old_returns)
    returned=f.form(staff,staff_route,staff_route+'/return')
    response=staff.submit(returned,{'lineId':line[0],'quantity':'1','reason':'Fictional goods received','confirmReceived':'true'})
    f.check('Linked return updates original finance credit and stock',response.status==302 and stock_state()==(initial[0]-1,initial[1]) and f.scalar('SELECT COUNT(*) FROM StockDocumentReturns WHERE FinanceDocumentId=?',(finance,))==old_returns+1)
    response=staff.submit(returned,{'lineId':line[0],'quantity':'1','reason':'Fictional goods received','confirmReceived':'true'})
    f.check('Return retry token does not double restock',response.status==302 and stock_state()==(initial[0]-1,initial[1]))
    f.check('No fictional payment was created for ecommerce order',f.scalar('SELECT COUNT(*) FROM FinancePaymentAllocations WHERE FinanceDocumentId=?',(finance,))==0)
    # Independent second order exercises the customer cancellation and release path.
    customer.submit(f.form(customer,'/Ecommerce','/Ecommerce/cart/line'),{'productId':product,'quantity':'1'})
    response=customer.submit(f.form(customer,'/Ecommerce/cart','/Ecommerce/checkout'),{'confirmOrder':'true'})
    cancelled=int(response.location.rsplit('/',1)[1]); cancel_route=f'/Ecommerce/orders/{cancelled}'; cancel=f.form(customer,cancel_route,cancel_route+'/cancel')
    forged=staff.request(cancel_route+'/cancel',fields=dict(cancel['fields'],reason='Other customer'))
    # The other customer's CSRF-bound cookie rejects the copied token before any business write.
    f.check('Copied cross-session cancellation form cannot mutate another customer order',forged.status==400 and state(cancelled)[0]=='Submitted')
    own_csrf=Forms(f.page(staff,'/Ecommerce/orders').text).get('/Account/Logout')['fields']['__RequestVerificationToken']
    forged=staff.request(cancel_route+'/cancel',fields=dict(cancel['fields'],__RequestVerificationToken=own_csrf,reason='Other customer'))
    f.check('Valid-CSRF cross-customer cancellation is denied by ownership check',forged.status==302 and state(cancelled)[0]=='Submitted')
    response=customer.submit(cancel,{'reason':'Fictional customer cancellation'})
    f.check('Customer cancellation releases reservation without stock/GL change',response.status==302 and state(cancelled)[0]=='Cancelled' and stock_state()==(initial[0]-1,initial[1]))
    customer.submit(cancel,{'reason':'Fictional customer cancellation'})
    f.check('Repeated cancellation cannot release twice',stock_state()==(initial[0]-1,initial[1]))
    filtered=f.page(customer,'/Ecommerce/orders?status=Cancelled&search=WEB-&page=999')
    f.check('Customer order filter and bounded pagination render cancelled order',f.scalar('SELECT Reference FROM EcommerceOrders WHERE Id=?',(cancelled,)) in filtered.text)
    f.page(staff,'/Ecommerce/staff/orders?status=Fulfilled&search=WEB-&page=1')
    # Exercise configured precision through real legacy finance MVC forms too.
    usd_staff=f.login(2,reviewer=True)
    usd_company=f.scalar("SELECT Id FROM Companies WHERE Slug='demo-farm-2'")
    usd_document=f.scalar('SELECT FinanceDocumentId FROM EcommerceFulfillments WHERE CompanyId=?',(usd_company,))
    accounts=f.page(usd_staff,'/Accounts')
    f.check('USD receipt and bank controls use reviewed two-decimal precision','USD' in accounts.text and 'id="payment-amount" name="amount" type="number" min="0.01" step="0.01"' in accounts.text and 'id="bank-amount" name="amount" type="number" step="0.01"' in accounts.text)
    payments_before=f.scalar('SELECT COUNT(*) FROM FinancePayments WHERE CompanyId=?',(usd_company,))
    vouchers_before=f.scalar('SELECT COUNT(*) FROM Vouchers WHERE CompanyId=?',(usd_company,))
    payment=Forms(accounts.text).get('/Accounts/payment')
    response=usd_staff.submit(payment,{'documentId':usd_document,'reference':'HTTP-USD-TOO-PRECISE','amount':'0.001'})
    f.check('Real USD payment form rejects .001 with no payment or journal',response.status==302 and f.scalar('SELECT COUNT(*) FROM FinancePayments WHERE CompanyId=?',(usd_company,))==payments_before and f.scalar('SELECT COUNT(*) FROM Vouchers WHERE CompanyId=?',(usd_company,))==vouchers_before)
    f.check('Precision rejection explains reviewed currency to staff','permits 2 decimal places' in f.page(usd_staff,'/Accounts').text)
    response=usd_staff.submit(payment,{'documentId':usd_document,'reference':'HTTP-USD-VALID-RECEIPT','amount':'0.01'})
    f.check('Real USD payment form accepts representable manual receipt',response.status==302 and f.scalar("SELECT COUNT(*) FROM FinancePayments WHERE CompanyId=? AND Reference='HTTP-USD-VALID-RECEIPT'",(usd_company,))==1)
    bank=f.form(usd_staff,'/Accounts','/Accounts/bank-line')
    bank_before=f.scalar('SELECT COUNT(*) FROM BankStatementLines WHERE CompanyId=?',(usd_company,))
    response=usd_staff.submit(bank,{'reference':'HTTP-USD-INVALID-WITHDRAWAL','amount':'-0.001'})
    f.check('Real signed bank entry rejects sub-minor-unit withdrawal',response.status==302 and f.scalar('SELECT COUNT(*) FROM BankStatementLines WHERE CompanyId=?',(usd_company,))==bank_before)
    subscription=f.page(usd_staff,'/Subscription')
    f.check('Actual subscription history displays locked USD denomination','Currency decimal places' in subscription.text and 'USD' in subscription.text and 'Historical fractions remain visible' in subscription.text)
